/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * The binary expects an even number of command‑line arguments, each
 * argument pair representing an undirected edge between two vertices.
 *
 * Vertices are numbered 0 … 7 (the program works with a fixed size
 * graph of 8 vertices).  If any argument is not a non‑negative integer
 * smaller than 8, or if the number of arguments (excluding the program
 * name) is odd, the program prints the single line
 *
 *     INVALID_INPUT
 *
 * and exits with status 1.
 *
 * Otherwise the program builds the adjacency matrix, computes the
 * connected components with a breadth‑first search, and prints each
 * component on its own line in the form
 *
 *     <component_index>: {v0,v1,…,vk}
 *
 * where the vertices inside a component are listed in the order they
 * are discovered by the BFS (the first vertex of a component is the
 * smallest numbered vertex that has not been visited yet).  A newline
 * follows each closing brace.
 *
 * The program returns 0 on success.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8               /* fixed number of vertices */
#define QUEUE_SIZE MAXV

int main(int argc, char **argv)
{
    /* 1. Validate argument count – must be an even number (pairs of vertices). */
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* 2. Initialise adjacency matrix and read edges. */
    int adj[MAXV][MAXV] = { {0} };
    for (int i = 1; i + 1 < argc; i += 2) {
        char *endptr;
        long a = strtol(argv[i],   &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 1; }
        long b = strtol(argv[i+1], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 1; }

        if (a < 0 || a >= MAXV || b < 0 || b >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[a][b] = 1;
        adj[b][a] = 1;          /* undirected graph */
    }

    /* 3. BFS to find connected components. */
    bool visited[MAXV] = { false };
    int  queue[QUEUE_SIZE];
    int  comp_index = 0;

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;

        printf("%d: {", comp_index++);
        bool first = true;

        int qhead = 0, qtail = 0;
        queue[qtail++] = start;
        visited[start] = true;

        while (qhead < qtail) {
            int v = queue[qhead++];
            if (!first) putchar(',');
            printf("%d", v);
            first = false;

            for (int w = 0; w < MAXV; ++w) {
                if (adj[v][w] && !visited[w]) {
                    visited[w] = true;
                    queue[qtail++] = w;
                }
            }
        }
        putchar('}');
        putchar('\n');
    }

    return 0;
}
